SELECT
	String = 
	/* ManfCode */ ISNULL(LTRIM(RTRIM(STR(I.ManfCode, 5))),'') + '~' +
	/* DistID */ ISNULL(LTRIM(RTRIM(:as_distcode + REPLICATE(' ', 10 - LEN(:as_distcode)))), '') + '~' +
	/* InvCode */ ISNULL(LTRIM(RTRIM(STR(S.SaleInvCode, 10))), '') + '~' +
	/* Date */ ISNULL(LTRIM(RTRIM(REPLACE(CONVERT(VARCHAR(20), S.Date, 6), ' ', '-'))), '') + '~' +
