	/* CustName */ ISNULL(LTRIM(RTRIM(A.Name)), '') + '~' +
	/* AreaCode */ ISNULL(LTRIM(RTRIM(STR(AR.AreaCode,10))), '') + '~' +
	/* AreaName */ ISNULL(LTRIM(RTRIM(AR.Name)), '') + '~' +
	/* SubAreaCode */ ISNULL(LTRIM(RTRIM(STR(SAR.SubAreaCode, 10))), '') + '~' +
	/* SubAreaName */ ISNULL(LTRIM(RTRIM(SAR.Name)), '') + '~' +
	/* BatchNo */ ISNULL(LTRIM(RTRIM(D.Batch)), '') + '~' +
	/* TerritoryCode */ '~' +
	/* TerritoryName */ '~' +
	/* SPOCode */ ISNULL(LTRIM(RTRIM(STR(ISNULL(C.SalesManCode, ''), 10))), '') + '~' +
	/* SPOName */ ISNULL(LTRIM(RTRIM((SELECT SM.Name FROM SalesMan SM WHERE SM.SalesManCode = S.SManCode))), '') +  '~' +
	/* ICode */ ISNULL(LTRIM(RTRIM(STR(I.ICode, 10))), '') + '~' +
	/* IteMName */ ISNULL(LTRIM(RTRIM(I.Name)), '') + '~' +
	/* Packing */ ISNULL(LTRIM(RTRIM(ISNULL(I.PackingDesc, ''))), '') + '~' +
	/* TeamCode */ ISNULL(LTRIM(RTRIM(STR(I.ICatCode,10))), '') + '~' +
	/* TeamName */ ISNULL(LTRIM(RTRIM((SELECT IC.Name FROM ItemCategory IC WHERE IC.ICatCode = I.ICatCode))), '') + '~' +
	/* Qty */ ISNULL(LTRIM(RTRIM(STR(D.LooseQty, 10, 2))), '0.00') + '~' +
	/* Bonus */ ISNULL(LTRIM(RTRIM(STR(D.BonusQty, 10, 2))), '0.00') + '~' +
	/* SalePrice */ ISNULL(LTRIM(RTRIM(STR(D.SalePrice - D.ItemFlatDisc, 10, 2))), '0.00') + '~' +
	/* DiscPerc */ ISNULL(LTRIM(RTRIM(STR(D.DiscPerc, 10, 2))), '0.00') + '~' +
	/* SalesTax */ ISNULL(LTRIM(RTRIM(STR(D.GstPerc, 10, 2))), '0.00') + '~' +
	/* GrossAmt */ ISNULL(LTRIM(RTRIM(STR(D.LooseQty * (D.SalePrice - D.ItemFlatDisc), 10, 2))), '0.00') + '~' +
	/* DiscAmnt */ ISNULL(LTRIM(RTRIM(STR( (D.LooseQty * D.ItemFlatDisc) + 
		(D.LooseQty * (D.SalePrice - D.ItemFlatDisc) * D.DiscPerc * 0.01), 10, 2))), '0.00') + '~' +
	/* SalesTaxAmt */ ISNULL(LTRIM(RTRIM(STR( 
		((D.LooseQty + D.BonusQty) * D.UnitSalesTax) + 
		( (D.LooseQty * (D.SalePrice - D.ItemFlatDisc) * (1 - D.DiscPerc * 0.01)) * 
		D.GstPerc), 10, 2))), '0.00') + '~' +
	/* NetAmt */ ISNULL(LTRIM(RTRIM(STR( (D.LooseQty * (D.SalePrice - D.ItemFlatDisc)) + 
		((D.LooseQty + D.BonusQty) * D.UnitSalesTax) + 
		( (D.LooseQty * (D.SalePrice - D.ItemFlatDisc) * (1 - D.DiscPerc * 0.01)) * 
		D.GstPerc) -
		(D.LooseQty * (D.SalePrice - D.ItemFlatDisc) * D.DiscPerc * 0.01), 10, 2))), '0.00')
FROM
	SaleLedger S,
	SaleDetail D,
	Item I,
	Customer C,
	Area AR,
	SubArea SAR,
	Accounts A,
	CustomerCategory CC
WHERE
	S.Date >= :ad_startdate AND S.Date <= :ad_enddate AND
	S.SaleInvCode = D.SaleInvCode AND 
	D.ICode = I.ICode AND
	I.ManfCode = :ai_manfcode AND
	S.CustCode = C.CustCode AND 
	S.Posted = 'Y' AND
	C.AreaCode = AR.AreaCode AND
	C.SubAreaCode = SAR.SubAreaCode AND
	C.CustCode = A.AccCode AND
	C.CustCatCode = CC.CustCatCode
